fn average_download_speed_correct(downloads: &[HttpDownload]) -> Option<f64> {
    let active_downloads: Vec<f64> = downloads.iter().filter_map(|d| d.speed_kbps).collect();
    if active_downloads.is_empty() { return None; }
    let sum: f64 = active_downloads.iter().sum();
    Some(sum / active_downloads.len() as f64)
